mapper.select:
select con.Con_Name as conName,
f.file_relation_id as fileRelationId, qt.Qst_Name as qstName, qt.Qst_Code as qstCode, qt.Qst_Item as qstItem, c1.C_Name as qsrCname, c2.C_Name as qsrFzCname, u1.U_Name as qsrXdUname, mn.* from Qs_Record mn left join Qs_Type qt on qt.Qst_Id=mn.Qst_Id left join Con_Contract con on con.Con_Id=mn.Con_Id
left join Sys_Company c1 on c1.C_Id=mn.Qsr_Cid left join Sys_Company c2 on c2.C_Id=mn.Qsr_Fz_Cid left join Sys_User u1 on u1.U_Id=mn.Qsr_Xd_Uid left join Sys_File f on f.FileID=mn.Qsr_Id ${params.authSql}
order by mn.${params.sortFiled} ${params.sortType}
order by ${params.sortSideFiled} ${params.sortType}
order by mn.Qsr_Create_Time DESC

select
(sum( case when qr.Qsr_State!=3 and to_char(qr.Qsr_State_Time,'yyyy')=to_char(now(),'yyyy') then 1 else 0 end))
allCount,
(sum( case when qr.Qsr_State=7 and to_char(qr.Qsr_State_Time,'yyyy')=to_char(now(),'yyyy') then 1 else 0 end))
closeCount,
(sum( case when qr.Qsr_State!=7 and qr.Qsr_State!=3 and to_char(qr.Qsr_State_Time,'yyyy')=to_char(now(),'yyyy')
then 1 else 0 end)) processCount
from  Qs_Record qr left join  Pre_Project pro on qr.P_Id=pro.P_Id
where Qsr_Category=#{qsrCategory}
 and qr.Te_Id = #{teId} 

    and pro.P_Construction_Unit=#{pConstructionUnit}


    and pro.P_Competent_Department=#{pCompetentDepartment}

UNION ALL
select
(sum( case when Qsr_State!=3 and trunc((to_char(Qsr_State_Time,'mm')+2)/3)=trunc((to_char(sysdate,'mm')+2)/3)
then 1 else 0 end)) allCount,
(sum( case when Qsr_State=7 and trunc((to_char(Qsr_State_Time,'mm')+2)/3)=trunc((to_char(sysdate,'mm')+2)/3)
then 1 else 0 end)) closeCount,
(sum( case when Qsr_State!=7 and Qsr_State!=3 and
trunc((to_char(Qsr_State_Time,'mm')+2)/3)=trunc((to_char(sysdate,'mm')+2)/3) then 1 else 0 end)) processCount
from  Qs_Record qr left join  Pre_Project pro on qr.P_Id=pro.P_Id
where Qsr_Category=#{qsrCategory}
 and qr.Te_Id = #{teId} 

    and pro.P_Construction_Unit=#{pConstructionUnit}


    and pro.P_Competent_Department=#{pCompetentDepartment}

UNION ALL
