(sum( case when Qsr_State!=3 and  QUARTER(Qsr_State_Time) = QUARTER(NOW())
then 1 else 0 end)) allCount,
(sum( case when Qsr_State=7 and QUARTER(Qsr_State_Time) = QUARTER(NOW())
then 1 else 0 end)) closeCount,
(sum( case when Qsr_State!=7 and Qsr_State!=3 and QUARTER(Qsr_State_Time) = QUARTER(NOW())  then 1 else 0 end)) processCount
from Qs_Record qr left join Pre_Project pro on qr.P_Id=pro.P_Id
