SELECT
qr.qst_id AS qstId,
COUNT(DISTINCT qr.qsr_id) AS count,
SUM(CASE WHEN rec.Qsr_Rectify_Status = '03' THEN 1 ELSE 0 END) AS qsFinish
FROM qs_record qr
LEFT JOIN Qs_Plan_Task qpt ON qpt.id = qr.pt_id
LEFT JOIN pre_project pp ON pp.p_id = qpt.p_id
LEFT JOIN Qs_Record rec ON rec.Pt_Id = qpt.id AND rec.qsr_id = qr.qsr_id
left join Qs_Type qt on qt.Qst_Id=qr.Qst_Id

    qr.qst_id IS NOT NULL
    
        and qpt.pt_type = #{request.ptType}
    
    
        
            and qr.Qst_Id = #{request.qstId}
        
    
    
        and qt.severity_level in
        
            #{item}
        
    
    
        and qpt.State=#{request.state}
    
    
        and pp.P_Type = #{request.pType}
    
    
        and pp.p_name like concat('%',#{request.projectName},'%')
    
    
        and pp.p_name like concat('%',#{request.pName},'%')
    
    
        and qpt.pt_evaluation_time >= #{request.ptEvaluationTimeFilterStart}
    
    
        and qpt.pt_evaluation_time <= #{request.ptEvaluationTimeFilterEnd}
    
    
        
            and (qr.Qst_Id = #{request.qstId}  or
            qr.qst_id in
            
                #{typeId}
            )
        
        
            and qr.qst_id in
            
                #{typeId}
            
        
    
    
        
            and (qr.Qst_Id = #{request.qstId}  or
            qr.qst_id in
            
                #{ids}
            )
        
        
            and qr.qst_id in
            
                #{ids}
            
        
    

GROUP BY qr.qst_id
ORDER BY COUNT(DISTINCT qr.qsr_id) DESC

