select con.Con_Name as conName,
f.file_relation_id as fileRelationId, qt.Qst_Name as qstName, qt.Qst_Code as qstCode, qt.Qst_Item as qstItem, c1.C_Name as qsrCname, c2.C_Name as qsrFzCname, u1.U_Name as qsrXdUname, mn.* from Qs_Record mn left join Qs_Type qt on qt.Qst_Id=mn.Qst_Id left join Con_Contract con on con.Con_Id=mn.Con_Id
left join Sys_Company c1 on c1.C_Id=mn.Qsr_Cid left join Sys_Company c2 on c2.C_Id=mn.Qsr_Fz_Cid left join Sys_User u1 on u1.U_Id=mn.Qsr_Xd_Uid left join Sys_File f on f.FileID=mn.Qsr_Id
and mn.Qsr_Category = #{params.qsrCategory}
order by mn.${params.sortFiled} ${params.sortType}
order by ${params.sortSideFiled} ${params.sortType}
order by mn.Qsr_Create_Time DESC
